module Jekyll
  class Regenerator
    # Key under which the modification times of the site data files are stored
    # within the metadata file.
    DATA_FILES_KEY = "data_files"

    attr_reader :site, :metadata, :cache
    attr_accessor :disabled
    private :disabled, :disabled=

    def initialize(site)
      @site = site

      @data_files = []
      @data_file_mtines = {}
      @data_files_changed = false

      # Read metadata from file
      read_metadata

      # Initialize cache to an empty hash
      clear_cache
    end

# Clear the metadata and cache
#
# Returns nothing
def clear
  @metadata = {}
  @data_file_mtines = {}
  @data_files_changed = false
  clear_cache
end

def read_metadata
  @metadata =
    if !disabled? && File.file?(metadata_file)
      content = File.binread(metadata_file)

      begin
        Marshal.load(content)
      rescue TypeError
        SafeYAML.load(content)
      rescue ArgumentError => e
        Jekyll.logger.warn("Failed to load #{metadata_file}: #{e}")
        {}
      end
    else
      {}
    end

  stored_data_file_mtines = @metadata.delete(DATA_FILES_KEY)
  @data_file_mtines = stored_data_file_mtines.is_a?(Hash) ? stored_data_file_mtines : {}
end

def regenerate_page?(document)
  document.asset_file? || document.data["regenerate"] ||
    source_modified_or_dest_missing?(
      site.in_source_dir(document.relative_path), document.destination(@site.dest)
    ) || data_files_modified?
end

def regenerate_document?(document)
  !document.write? || document.data["regenerate"] ||
    source_modified_or_dest_missing?(
      document.path, document.destination(@site.dest)
    ) || data_files_modified?
end

# Compares the mtime of a data file against the mtime stored during the
# previous build and records the current mtime for the next one.
#
# Returns a boolean.
def data_file_modified_since_last_build?(path)
  stored_mtime = @data_file_mtines[path]
  if File.exist?(path)
    current_mtime = File.mtime(path)
    @data_file_mtines[path] = current_mtime
    stored_mtime.nil? || !stored_mtime.eql?(current_mtime)
  else
    @data_file_mtines.delete(path)
    !stored_mtime.nil?
  end
